/// A single todo entry: title, completion flag and creation time.
class TodoItem {
  const TodoItem({
    required this.id,
    required this.title,
    required this.done,
    required this.createdAt,
  });

  /// Unique id (timestamp + counter based, generated by [TodoStore]).
  final String id;

  /// The task text. Non-empty by construction (see [TodoStore.add]).
  final String title;

  /// Whether the task has been completed.
  final bool done;

  /// When the task was created.
  final DateTime createdAt;

  TodoItem copyWith({bool? done}) {
    return TodoItem(
      id: id,
      title: title,
      done: done ?? this.done,
      createdAt: createdAt,
    );
  }

  Map<String, Object?> toJson() {
    return {
      'id': id,
      'title': title,
      'done': done,
      'createdAt': createdAt.toIso8601String(),
    };
  }

  factory TodoItem.fromJson(Map<String, Object?> json) {
    return TodoItem(
      id: json['id'] as String,
      title: json['title'] as String,
      done: json['done'] as bool,
      createdAt:
          DateTime.parse(json['createdAt'] as String),
    );
  }
}
